INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p713990-pyp001', 'stk-user4307', 'PYP 001', 'info', '{"desc": "بعدين من قال لك انه فيه كمستري بالاوريا …!!\n\nاللي درسناه في مادة الفيزياء PYP001 هو عبارة عن مقدمة في الفيزياء والكيمياء والجيولوجيا ،،\n\nبس الغلط من الطلاب انهم سموا المادة فيزياء ،،\n\nلو كانت بس فيزياء كان اسم الكورس Phys 001 ،،\n\nبس الاسم الحالي للكورس PYP001 = prep. year program 001\n\n🙂", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/95674/14", "user": "user4307", "ts": 1286195467000, "tid": 95674, "pn": 14}}', 1286195467000, 1794835001, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p242481-pyp001', 'stk-red-devil', 'PYP 001', 'info', '{"desc": "مادة الفيزيكس…\n\nمادة صراحة مهي صعبة…\n\nبس لا تهملها…\n\nلانو الاهمال سبب الاخفاق فيها…\n\nطيب كيف طريقة المذاكرة…\n\nعن نفسي والله كنت أفهم من الكتاب…\n\nوأركز مع المدرس…\n\nوصلى الله وبارك…\n\nصح ما جبت فيها درجة مرررررررررررة يعني جيدة…\n\nلكن هذا اللي سويته فيها…\n\nبالنسبة للمدرسين…\n\nللأسف ما عندي خبرة…\n\nتحياتو", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/pyp001-pyp003/61322/3", "user": "red-devil", "ts": 1202336962000, "tid": 61322, "pn": 3}}', 1202336962000, 1794835001, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p242486-pyp001', 'stk-my_heart', 'PYP 001', 'info', '{"desc": "شوف الفزكس مثلها مثل باقي المواد في الاوريا عباره عن كوكتيل من كل التخصصات العلمية المعروفه(كيميا -فيزيا -جيلوجيا )\nمارح تلاقي الكثير من الملخصات الخاصة بهذي المادة بختصار التركيز مع المدرس وتحضير الدروس والترجمة الصحيحة كفيلة انها تخليك تعدي انا كنت عند استاذ عناية بيض الله وجهه كان نعم المدرس لنا رائع في الشرح والمعاملة والرحمة كان يعتمد معانا الكويزات لانه وجد ان الهوم وركات كلها على النت محلوله 🙂 فقرر انه تكون واجباتنا عبارة عن كويزات مستمره بصراحة والحق يقال استاذ من الطراز الاول يعرف الطالب المجتهد من المتلاعب حتى لو الطالب المجتهد اخفق في بعض الكويزات يراعي اجتهادة وحصل هذا معي شخصيا واعطاني درجة المشاركة درجة رائعه بيض الله وجهه والحمدالله نجحت بتقدير B 🙂 والحمدالله الف شكر استاذ فؤاد عناية\n\nMY HEART", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/pyp001-pyp003/61322/4", "user": "My_Heart", "ts": 1202338798000, "tid": 61322, "pn": 4}}', 1202338798000, 1794835001, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p242657-pyp001', 'stk-d_a_r_k_h', 'PYP 001', 'info', '{"desc": "المدرسين من وجهة نظري ما يفرقون كثير لأن المنهج مو ذاك الزود. ويعتمد على الطالب ودراسته من الدرجه الأولى…\n\nيعني في الفيزياء… لو تشتري نوت 3 من الجمعية في أول اسبوع… و تدرس كل درس بوقته ( يعني: تترجم الكلمات اللي ما تعرفها في الدرس ) لأن الفيزياء نصها فوكاب… راح تكو ن سهله بالنسبه لك و دراسة الفيزياء أعتقد إنها عصفورين في حجر واحد… أول شيء علشان الكورس… وثاني شيء راح تطور الانقليزي عند الشخص…\n\nوالمهارات الجامعية احضر… وسوّ الأشياء اللي يطلبها منك هووم وورك و برزينتيشن بالبور بوينت وهذي كلها علشان الدرجات المرتفعه A+ و A …\n\nشكرا ً", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/pyp001-pyp003/61322/16", "user": "D_a_r_K_h", "ts": 1202422907000, "tid": 61322, "pn": 16}}', 1202422907000, 1794835001, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1116595-pyp001', 'stk-user6441', 'PYP 001', 'info', '{"desc": "collection 1\n\nهدية ثانية لأورياتنا الحلوين الي معهم فيزكس cool2.gifتجميع كويزات وسلايدات د. تيسير أبو الروب “من أفضل دكاترة هالمادة”\n+ شوية أولد إكزامز\n+حلولي للأونلاين هومورك\n+ ماتيريال سابق للترمين 091 و 101 “موجودين بالتراكر سابقاً”\n\nموفقين يا كتاكيت يا حلوين\n\nhttp://tracker.kfupm.edu.sa/index.php?page=torrent-details&id=45aa2153f30e3fd430ef5597be71da80f62910a1\n\n-----------------------------\nملفات فيها دروس الفيزياء 001\n\nو حلول الاون لاين هوم وورك و الاون لاين كويزيز\n\nو عدة أشياء اضافية عن المنهج\n\nلترمي 091 &101\nPhysical science (PYP-001)\nhttp://tracker.kfupm.edu.sa/index.php?page=torrent-details&id=cdaf6f8f101338057e40e37d00cfc6c00d813197", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/pyp001-note-physics-notes-plz/134548/8", "user": "user6441", "ts": 1352780782000, "tid": 134548, "pn": 8}}', 1352780782000, 1794835001, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p362139-pyp001', 'stk-dr.mohtaref', 'PYP 001', 'info', '{"desc": "لا انصحك بأن تتعب نفسك بهذا الموضوع :shushing_face:\n\nأعتبر أنك ستحصل في اسوء الأمور على مجموع 50 درجة كي تريح نفسك من مجرد توقعات …\n\nمن المعروف أن موضوع درجة إجتياز المادة لايستطيع أن يحكمه لا شخص ولا شخصين\nإن كنت مهتم بمعرفة توقعات الطلاب لهذه الدرجة ستجد اختلافات كثيرة بالتوقعات وستجد الكثير من المواضيع التي انشأوها الطلاب لتوقع درجة لا يستطيع أحد الجزم بها …\n\nنصيحة … لاتضيع وقتك … ابدأ بالإجتهاد الآن , ولكل مجتهد نصيب … 👍\n\nتقبل تحياتي\n, وبالتوفيق 🙂", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/how-can-i-study-physics-pyp001/70165/20", "user": "Dr.Mohtaref", "ts": 1233946317000, "tid": 70165, "pn": 20}}', 1233946317000, 1794835001, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p396750-pyp001', 'stk-user2352', 'PYP 001', 'info', '{"desc": "خذوها نصيحة بشكل عام قبل اتخاذ القرار في اختيار التخصص:\n\nإذا تشوف نفسك فالح في الرياضيات (درجتك تكون +c وما فوق فكل من 001 و002 ) وفي الفزكس pyp001 c وما فوق وعندك استعداد للكرف والمذاكرة أولا بأول وحل الهوموركات فا ختر هندسة سواء كهربائية أو ميكانيكية أو نظم أو مدنية أو نظم تحكم وقياس ،، وإذا كنت فلتة في البرمجة وحب صناعة البرامج فاختر هندسة البرمجيات أو هندسة الحاسب ،، وإذا كنت تحب الكيمياء وتهواها فاختر هندسة كيميائية وإذا أردت التخصص الممتع والسهل الممتنع يربط الهندسة بالادارة فمالك إلاهندسة النظم الصناعية ،،،\n\nوإذا كان مستواك في الماث مش ولا بد يعني يا الله بالبركة تعدي ولا تحب الفيزياء والكيمياء فا أبعد عن الهندسة بكافة تخصصاتها وعن الكمبيوتر ،، وسجل في كلية الادارة الصناعية وهذا لا يعني إن كلية الادارة سهلة ولكن تعتبر أقل ضغط من الهندسة وتصلح للطالب القوي في اللغة الانجليزية ويحب التحليل والاستنتاج ،،،،،،،", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/72411/20", "user": "user2352", "ts": 1240650178000, "tid": 72411, "pn": 20}}', 1240650178000, 1794835001, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p152306-pyp001', 'stk-doubleclick', 'PYP 001', 'info', '{"desc": "إسم المدرس : فؤاد عناية\nإسم المادة : pyp 001\nتجربتي معه : مدرس ممتاز\nمتحمس وشرحة جيد\nيجب الاهتمام في كويزاته\nعنده الواجبات بالتسليم\nمشكلته بالنسبة لي كانت\nفي البداية حيث أنه\nلا يحبذ الكلام بالعربي إطلاقاً\nوبالنسبة لـ class work\nيوزع الدرجة من 260\n90 على الواجبات\n50 على الحضور\n50 على الكويزات\n50 على تسجيل الدخول وحل web CT\n20 على مقال تحضره عن أي موضوع فيزيائي\nالمدرس بشكل عام ممتاز وأخلاقه عالية", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/54933/3", "user": "DOUBLECLICK", "ts": 1171358474000, "tid": 54933, "pn": 3}}', 1171358474000, 1794835001, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1439050-pyp001', 'stk-_20161', 'PYP 001', 'info', '{"desc": "السلام عليكم\n\nاقدم لكم كتاب الفيزيكس pyp 001 بنسخة pdf للميتيرال المطلوب قابل للطباعة\n\nافضل بكثير من حمل الكتاب الثقيل كل حصة حيث يحتوي الكتاب على حوالي 1300 صفحة :sneezing_face:\n\nبينما الملف يحتوي على 270 صفحة 😉\n\nالرابط : DOC002.PDF - Google Drive\n\nو اقدم ملف يحتوي على ملخصات سريعة للدروس مترجمة عربي و الهوموركات القديمة و حلول تقويم الكتاب\n\nالرابط : PYP 001\n\nملاحظات :\n\n1- ذاكر من الكتاب ، ولا تعتمد أي نوته او ملخصات .\n\n2- الملخصات التي وضعتها تحتوي على الافكار الرئيسية للدرس من study guide و بعض المعلومات المهمة من الدرس ، يعني ذاكر من الكتاب و اترك الملخصات كمراجعة .\n\n3- الملخصات السريعة من عملي يعني من طالب و ليس من مدرس 🙄 .\n\n4- ركز على اسئلة تقويم الكتاب تجي بعضها في الكويزات و المياجر ( وضعت اجابات الاسئلة بالملف ) .\n\n5- الهوموركات التي وضعتها هي لترم 151 ، لكن مذاكرتها تعطيك افكار اكثر .\n\n6- الكورس سهل يضم اساسيات المواد الثلاث : فيزياء ، كيمياء ، علم الارض .\n\n7- في العادة يتغير الكتاب كل سنتين تقريباً ، لكن تظل المواضيع هي نفسها .\n\nتحياتي 🌹", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/pyp-001-pdf/171628/1", "user": "_20161", "ts": 1452911510000, "tid": 171628, "pn": 1}}', 1452911510000, 1794835001, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p161325-pyp001', 'stk-user1838', 'PYP 001', 'info', '{"desc": "يا أخ bdullah3 أنا ماقلت هذا الكلام إلأ من تجربتي في الماث في001 ون ما كنت أحل الواجبات فكنت أخذ وقت طويل للمذاكرة وقت الميجر بس هالسمستر في 002 بدأت أحل الواجبات أول بأول والحمد لله يومين كملت المذاكرة وبقية الأيام بس أحل old exam والحمد لله جبت درجة طيبة في الإختبار", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/pyp001/55644/7", "user": "user1838", "ts": 1175882108000, "tid": 55644, "pn": 7}}', 1175882108000, 1794835001, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1423993-pyp001', 'stk-hussain_haiyan', 'PYP 001', 'info', '{"desc": "المشكلة الترم الماضي الي هو 142 غيروا الكتاب …\nوالكتاب الجديد الواحـد يستثقل يحمله معـاه للكلاس ، آكبر حتى من كتاب الماث : /\nونـص الي بالكتاب ذا مسحووب عليه بس كم شابتر ندرس منه …\n\nفـ ما أعتقد موجوده نوتات تذاكر منها حالياً …\nمدرسي أنا كان يشرح لنا على سلايدات من الكورس حق الكتاب القديم\nكان الترتيب يختلف ندرس أول شيء فيزياء قوانين نيوتن وغيرها بعدها ندخل في الكيمياء وفي النهاية الجيولوجياء …\nوكان في آختلاف بسيط من ناحية الدروس …\nأذكر شرح لنا كم شيء وآختبرنا فيه كويزات ما شفته موجود بالكتاب أصلاً\n\nبس على كلِِ الكتاب مفيد من ناحية الشرح والأمثلة ، في الآختبارات المياجر و حتى الفاينال\nأغلب الأمثلة الي جابوها موجوده أصلاً بالكتاب بس أغلب الطلاب ما يفتح الكتاب …\n\nأما المسائل الي بالكتاب كلها سهله وبسيطه مو مثل الي يجيبوها بالمياجر أو الفاينال", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/pyp001/169272/3", "user": "Hussain_Haiyan", "ts": 1439634503000, "tid": 169272, "pn": 3}}', 1439634503000, 1794835001, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1263968-pyp001', 'stk-user9213', 'PYP 001', 'info', '{"desc": "شوف انصحك بالكتاب بس اذا كنت مضغوط وماعندك وقت فاقرأ الكتاب قراءة سريعة وراجع الرسوم البيانية لانها مهممممممممه يجيك عليها سؤال او سؤالين بالميجر و الصور اللي تساعدك باالفهم و فالمراجعة استلم نوت جواد و فالك الـ a+ اعيد و اقول نوت جواد هي الامثل و بقوة", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/pyp-001/149553/7", "user": "user9213", "ts": 1379192770000, "tid": 149553, "pn": 7}}', 1379192770000, 1794835001, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p214816-pyp001', 'stk-user2536', 'PYP 001', 'info', '{"desc": "يا رجال لا تشتري نوت مكي ولا نوت بهلولي ولا يحزنون … وانا اعرف ان قصدك تساعده يا هجراوي …\nبس كل المنهج اللي يدرسه بالاوريا مختصر جداااا… صح انه يتكرر له بالجبل ومفصل …\nبس المطلوب منه في الاوريا يفهم زين ويركز … عشان اذا جا الجبل يصير عنده فكرة …\nمهب يدرس بالتفصيل شي ما وصله ,\n\nنصيحتي اخوي ذاكر الكتااب بالمقام الاول … صح صعب شوي … لكن مع المذاكرة الدوريه … بيكون اسهل …\nواهم شي هي الشيك بوينت ., وتذكر ان الفيزكس فهم وبس فهم\nواذا اخذتها حفظ اتحداااااك تعدي اكثر من سي بلس …\nواذا تبي السي بلس احفظ …\nوموفق …", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/pyp001/59240/15", "user": "user2536", "ts": 1193942703000, "tid": 59240, "pn": 15}}', 1193942703000, 1794835001, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p215594-pyp001', 'stk-user2924', 'PYP 001', 'info', '{"desc": "الإخوة الكرام\n\nانا اشكر لكم واحد واحدا هذا التفاعل الجميل\nوالحمد لله الازمة عدت وفهمت\nلكن عاد الاختبار الله يستر ويعين و بس\n\nاخي هجراوي ،\nنصيحتك رائعة جدا لأوريا ادفانسد\nمش حنا الغلبانين 😦\n\nلنا الله 🙂\n\n**\nبالنسبة للاولد اقزام ففي الموقع اشياء قليلة جدا (اقصد موقع المادة) يعني النوت اللي في الجمعية احسن بكثير فيها اختبارات وفوكاب واشياء طيبة\nلكن يعني الكتاب هذا امر لازم منه و لا تحاولون تتعودون على غيره إلا كامور اضافية وتكميلية\n\nولغة الكتاب موجهة للأطفال يعني ( وانظر للإهداء في بداية الكتاب )\nوان شاء الله مافي مشاكل\n\nطبعا لاتنسون الحاسبة في الاختبار\nو ممنوع الدكشنري\nراجعوا موقع الفيزياء للتفاصيل الاخرى عن الاختبار\n\n<< اوريا صحيح ، لكن مش معناه ماعرف ولا حاجة\nتحياتي", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/pyp001/59240/19", "user": "user2924", "ts": 1194206410000, "tid": 59240, "pn": 19}}', 1194206410000, 1794835001, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p255537-pyp001', 'stk-user3033', 'PYP 001', 'info', '{"desc": "مشكوور أخــوي على مجهوودكـ …\n\nمع إني مخلص الفزكس السمستر اللي راح … بس أحب اقول للشباب لا تغركـم درجات الميجـر الأول … لإن المواضيع بالنسبة للأختبار الثاني راح تكون سهلة نسبياً … يعني حاول تشـد حيلك عشان تعدي تدخل الفاينل وأنت مرتاح …\n\nوبالنسبة للي ما حالفهم الحـظ بهالميجر يحاولون يعوضون بالميجـر الجاي … ويشدون حيلهم بالكويزات ولا ينسون إن بيد المـدرس 20 درجة …\n\nوبالتووفيق جميعاً …", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/pyp-001/62351/2", "user": "user3033", "ts": 1206468534000, "tid": 62351, "pn": 2}}', 1206468534000, 1794835001, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1468597-pyp001', 'stk-najiali', 'PYP 001', 'info', '{"desc": "فزكس الاوريا مافيه صعوبة ولا يحتاج جهد كثير. المهم فيه (بالنسبة لي شخصياً) مستواك في اللغة الإنجليزية. لان أغلب الأمور اللي راح تمر عليها كلها أساسيات في الفيزياء والكيمياء والعلم الأرض بس باللغة الأنجليزية. إذا حاب تلحق على اللي فاتك, شوف أحد زملائك في الكلاس وخله يعطيك النوتات اللي كتبها. شخصياً الكتاب كافي إنه يفيدك باللي تم شرحه في الكلاس لكن مايمنع إنك تطلب أحد الزملاء إنه يوضح لك بالضبط ايش اللي تم شرحه.\n\n((اليوتيوب أداة مهمة جداً في شرح أي شيء لم تفهمه في أي مادة))\n\nبالتوفيق لكل خير,", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/pyp-001/176103/2", "user": "NajiAli", "ts": 1487442146000, "tid": 176103, "pn": 2}}', 1487442146000, 1794835001, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
