INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p83247-pyp001', 'stk-user1222', 'PYP 001', 'srcP', '{"html": "السلام عليكم ورحمة الله وبركاته…<br><br>تحية طيبة<br><br>كيف حال الشباب…<br><br>دي أسئلة مراجعة للفيزيكال ساينس من موقع الكتاب + بعض الهوومووركات من موقع المادة…<br><br>لا تعتمدو عليها اعتماد كلي والله الله بالـA بلسات<br><br>الملفات مرفقة<br><br>أطيب الأماني بأعلى الدرجات<br><br>معدن<br><br>​<span data-fid=\"stk-f83247-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​<br>​<span data-fid=\"stk-f83247-1\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f83247-0": {"name": "h.w pyp001.doc", "v": "data:application/msword;base64,"}, "stk-f83247-1": {"name": "quiz.zip", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/6cd418282cddca6a61364274fae1c0efc9b4a2525f78cfec0011e1338bf079f6"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/pyp001/48900/1", "user": "user1222", "ts": 1130019545000, "tid": 48900, "pn": 1}}', 1130019545000, 1794835001, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p613358-pyp001', 'stk-user7000', 'PYP 001', 'srcP', '{"html": "للي طلب حل hw 11<br>في المرفقات<br><br>​<span data-fid=\"stk-f613358-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f613358-0": {"name": "h.w 11.doc", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/b1de1ad7aed36c60a64a00e846fd85cec047f122c0005269fce5bc6e2c9d3ccf"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/11-hw-11-pyp001/88696/1", "user": "user7000", "ts": 1274597356000, "tid": 88696, "pn": 1}}', 1274597356000, 1794835001, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1159146-pyp001', 'stk-brooo_ittihad', 'PYP 001', 'srcP', '{"html": "ـآدعيلي<br><br>🌹<br><br>​<span data-fid=\"stk-f1159146-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f1159146-0": {"name": "PYP001-121-MI-20Q-Website.pdf", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/8f95ce755a2c1f9342795a19f531dfa964de0efdac2e9aae1cdfe02894830c1c"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/137916/2", "user": "BRoOo_IttIhad", "ts": 1357632909000, "tid": 137916, "pn": 2}}', 1357632909000, 1794835001, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-kirsty13-pyp001', 'stk-kirsty13', 'PYP 001', 'doc', '{"docs": [{"id": "stk-dr-f68477", "n": "Dr. Abdallah Abulkibash", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "181-PYP001\n\nالتحضير :كل كلاس,لكن حبيب تخش بعدها بنص ساعة يحضرك ما يحاسب على التاخير ابدا ويسمح بالميكب لدرجة اتذكر 4 طلاب اسبوعيا من سكشن الصبح يوم الاربعاء يجون عندنا\nطريقة الشرح : للامانة سيئة جدا وتجيب النوم واذا سالته عن شي يبدا يلخبط ويلحس لك معلوماتك القديمة 🙂 باختصار ماعنده قدرة ايصال المعلومة نهائيا\nالكويزات : سهلة جدا وعادي تكتب بالعربي اذا الانجليزي عندك تعبان ويمديك تفتح جوالك وتترجم اذا تبي 😁\nالمياجر: من الديبارتمنت\nالفاينلات : من الديبارتمنت\nالقريد النهائي: خذت عنده C واغلب سكشنا كان +C , واعطيه B\nالصوت: هادي جدا\nإضافات : هالدكتور زين للي يبي ينجح بدون قريد لان الكلاس وورك بيكون عالي وابدا ما شفت اخلاق مثل اخلاقه عسل مرة لكن تبي قريد مانصحك قيه نهائيا :no_entry_sign:", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1505418-pyp001", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/abdallah-abulkibash/68477/29", "user": "Kirsty13", "ts": 1548688927000, "tid": 68477, "pn": 29}}]}', 1548688927000, 1794835001, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abdullah2015-pyp001', 'stk-abdullah2015', 'PYP 001', 'doc', '{"docs": [{"id": "stk-dr-f68489", "n": "Dr. Mohammed Musazey", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "أخذت عنده PYP001 ترم 152\n\nالتحضير :\nيومياً في بداية الكلاس، ويكره المتأخرين :).\nطريقة الشرح :\nعلى السبورة يشرح الكونسبت، شرحه حلو ومفهوم.\nالكويزات :\nتمتاز كويزاته إنها (أحياناً) زي ما قالوا الأخوة اللي فوق بأن ما لها دخل باللي شرحه، لكنها سهلة إلى متوسطة بحكم إن المنهج سهل أساساً والماتيريال محدودة.\nالمياجر:\nكومون.\nالفاينلات :\nكومون.\nالقريد النهائي:\nB+\nالصوت:\nواضح.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1457553-pyp001", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohammed-musazey/68489/59", "user": "Abdullah2015", "ts": 1473795111000, "tid": 68489, "pn": 59}}]}', 1473795111000, 1794835001, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mr_sleepy-pyp001', 'stk-mr_sleepy', 'PYP 001', 'doc', '{"docs": [{"id": "stk-dr-f68498", "n": "Dr. Mohammed Al-Solami", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "بصراحة الدكتور طيب ومتعاون جدا درسني pyp001\nولكنه بصراحة مايعرف يشرح .ما تفهم منه شي الكلمات هي نفسها يعيدها.حتى لو سئلته سؤال\nيجاوب علية ومع ذلك ماتفهم 😦\nالكويزات) متوسطة وتعتمد على القوانين اللي في الكتاب\nالتحضير) يوميا\n\nالقريد النهائي =c", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p408751-pyp001", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohammed-al-solami/68498/3", "user": "Mr_Sleepy", "ts": 1243849272000, "tid": 68498, "pn": 3}}]}', 1243849272000, 1794835001, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-hussain_haiyan-pyp001', 'stk-hussain_haiyan', 'PYP 001', 'doc', '{"docs": [{"id": "stk-dr-f115380", "n": "Dr. Fazal Ur-Rehman", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "درست عنده في ترم 142 - فزيكس الآوريا - PYP001\n\nالتحضير : في التحضير نظامي ، يحضـر ببرنامج الأكسل مع بداية أول دقيقة بالكلاس\nو التأخير يروحون له الطلاب بنهاية الكلاس يسجلهم\nيعني آحرص إنك تحضر على الوقت …\n\nطريقة الشرح : يشرح على سلايدات باور بوينت وبعض الأوقات يستخدم السبورة للشرح\n\nالكويزات :\nالكويزات مستواها متوسط ، يحتاج إنك تفتح الكتاب وتذاكر أو تكون منتبه له وهو يشرح\nو آذكر آختبرنا كويزين تقريباً مفاجئ …\n\nالمياجر: Common\nالفاينلات : Common\nالقريد النهائي: B\n\nالصوت: كويس و وآضـح …\n\n**إضافات :**هو ما قال لنا من وين بس من الأكسنت حقه هندي تقريباً ، مسلم طبعاً ويعرف شويه عربي … 😆\nألاحظه يتعلم الكتابة بالعربي و بعض الأوقات لما يشرح لنا مصطلح يقول لنا آسم المصطلح بالعربي\nوإذا ما يعرف معنى الكلمة الي يشرحها يسألنا آيش معناها بالعربي …\n\nو حسب ما قال لنا في أول كلاس آنه درس في الجامعة مثلنا بعدها طلع أمريكا يكمل دراسته\nورجـع الآن للجامعة يدرس … 😆\nأما هو كـ شخصية آنسان حبوب و طيب و خلوق … في الشرح يحب يشارك الكلاس معاه كامل\nوالي ما يشارك يجبره على المشاركة سـواء جلست قدام ولا بالنص ولا ورى ، ما يفيدك …\nهذي آحدى آيجابياته ما يخلي أحد في حاله توقع يسألك في أي لحظه … 😆\nولو بتطقطق على جوالك هم ما راح يخليك بيصيدك …\nوبعض الطلاب يجلس ورى وينام ، هذا الله يعينه إذا صاده\nيمسك كرسيه و يوديه قدامه ويستلمه كل شوي أسئلة هههههههههه\nو أيضاً يحفظ أسماء طلابه …\nو طبعاً كل هذا ولا مرة شفته عصب … زي ما قلت لك آنسان خلوق\nمن النوعية الي يعرفون يسيطرون على الكلاس\n^ في الواقع أنا يعجبوني هالنوعية من الناس يفرض سيطرته على الكلاس بقوة … 😛", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1424573-pyp001", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/fazal-ur-rehman/115380/4", "user": "Hussain_Haiyan", "ts": 1439986625000, "tid": 115380, "pn": 4}}]}', 1439986625000, 1794835001, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-faisal_19-pyp001', 'stk-faisal_19', 'PYP 001', 'doc', '{"docs": [{"id": "stk-dr-f172587", "n": "Dr. Giacinto Genco", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "PYP001 - 161\n\nالتحضير : يومياً\nطريقة الشرح : هو يحاول يشرح وبعض الاشياء متمكن منها لكنه يتفرع كثيييير, أغلب الحصه يضيع الوقت في شي ما منه فائدة.\nالكويزات : متوسطة الى صعبة ، يحط الاسئلة بناءاً على معلومات من كتب غير كتاب الكورس بإعترافه!\nالمياجر: كومون\nالفاينلات : كومون\nالقريد النهائي: B وطلعت من الكورس بـ A والسبب توفيق الله ثم اني تلاحقت على نفسي وصرت احضر عند استاذ ثاني بالاضافه له عشان التحضير.\nالصوت: جيد جداً.\n\nإضافات : محترم وأخلاق، يتطرق لأشياء كثيرة ما لها اي فايدة في الكورس ويتفرع كثير زي ما قلت مثل اثبات دالة الساين والكوساين والبارابولا ، الكويزات غالباً 3 اسئلة من 5 ما لها علاقة بالدروس او تكون عن الدروس بس بزيادات معقدة وما شرحها ومو مطلوبة في الكورس.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1467472-pyp001", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/giacinto-genco/172587/3", "user": "Faisal_19", "ts": 1486066617000, "tid": 172587, "pn": 3}}, {"id": "stk-dr-f115380", "n": "Dr. Fazal Ur-Rehman", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "PYP001 - 161\n\nالتحضير : يومياً، مايعطي ابسنت الا للي ما يحضر ابد او ما يقدّره ويحترمه.\nطريقة الشرح : سلايدات خاصة فيه ويسمح لك انك تصورها بالجوال بس + شاملة لكن يفضّل تقرأ الكتاب.\nالكويزات : سهلة جداً بسبب شرحه الوافي والواضح، كويزاتي كانت تقريباً كاملة كلها او قريب من الفل.\nالمياجر: كومون\nالفاينلات : كومون\nالقريد النهائي: لو فيه أكثر من A+ فهي قليلة في حقه !\nالصوت: واضح جداً.\n\nإضافات : الاستاذ هذا كنت احضر عنده كمستمع لسوء شرح استاذي يعني ما يقدر يعطيني اي درجه لانه مو مدرسي الاساسي ومع ذلك ما فوت ولا حصه عنده لانه يمتعك بشرحه الي اقل ما تقول عنه بطططل، يقدّر الي يهتم في العلم لدرجة انه يهتم فيني على بعض باقي طلابه، ما يحب اللي يجلس ورا ويفهي وتوقع سؤال مفاجئ، ما كنت اروح الاوفس الاور الا عنده ، استفد منه قدر المستطاع دكتور بطططططططططططططططل ❤️ ❤️ ❤️", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1467473-pyp001", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/fazal-ur-rehman/115380/9", "user": "Faisal_19", "ts": 1486067806000, "tid": 115380, "pn": 9}}]}', 1486066617000, 1794835001, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-sultan_salman_1419-pyp001', 'stk-sultan_salman_1419', 'PYP 001', 'doc', '{"docs": [{"id": "stk-dr-f115380", "n": "Dr. Fazal Ur-Rehman", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "PYP001 … Term 161\n\nالتحضير : في أول دقيقة … يعيد مرة ثانية بعد ما يخلص … يمديك تجيه أخر الكلاس وتذكره عشان ما يحطك ابسنت ( في بداية الترم يعطيك بريزنت وفي نهاية الترم يعطيك ليت )\n\nطريقة الشرح : ممتازة … يحاول يحاكي الدرس قد ما يقدر … لا تستغرب يسوي أشياء غربية ( يجري … يوقف على الطاولة … يرمي بعض الاشياء …الخ) … عشان يوضح نقطة معينة في الدرس\n\nالكويزات : كويزاته ما يكررها بحيث اذا كان فيه سكشن قبلكم يختبر … فالكويز للسكاشن اللي بعده راح يكون مثله تماما … من ناحية المياجر: أقيمها فوق المتوسطة\n\nالمياجر :كومون\nالفاينلات : كومون\nالقريد النهائي: +A\nالصوت: جيد جدا إلى ممتاز\nإضافات :\nأستاذ متمكن في المادة … خلوق ومتعاون … أتوقع أنه من أفضل المدرسين في هذا الكورس … حاول تجلس في الامام عشان يعرفك … الباس في الكورس سهل … لكن القريد صعب نوعا ما … حاول تطلع بأوفر الل ممتاز قبل الفاينل عشان ترتاح", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1479967-pyp001", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/fazal-ur-rehman/115380/10", "user": "sultan_salman_1419", "ts": 1505032854000, "tid": 115380, "pn": 10}}]}', 1505032854000, 1794835001, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-to_be_engineer-pyp001', 'stk-to_be_engineer', 'PYP 001', 'doc', '{"docs": [{"id": "stk-dr-f115380", "n": "Dr. Fazal Ur-Rehman", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "pyp001-163\n\nالتحضير : اول خمس دقايق… مايحب التأخير وممكن يسألك ليش متأخر.\nطريقة الشرح : عنده سلايدات يشرح منها مافيها تفاصيل كثيرة غالبا رؤوس اقلام… يشرح من قلب يحاول يتعمق في الشي لين تفهمه ويعيده اكثر من مره وكثير من الاحيان يحاول يطبق الشي قدامك عشان تفهمه زين ودايم يسأل عشان يتأكد من وصول المعلومة خصوصا اللي يشوفه مسرح… عن نفسي استمتعت بشرحه كثير وطلعت بقريد كويس.\nالكويزات : اذا عطاكم واجب اعرف انه بيجيك في الكويز … ويجيب شوية اولد اقزام ويمكن سؤال بيسك. بشكل عام متوسطة تميل للصعوبة اذا اهتميت بتصير سهلة.\nالمياجر: كان هو اللي يسوي المياجر في الصيفي… الاول كان سهل… الثاني كان متوسط لان افرج الاول كان مرتفع.\nالفاينلات : كان سهل جدا واغلبه جيولوجيا… ما كان يبي احد يرسب … كم انت عظيم يا فضل ❤️.\nالقريد النهائي: A+\nالصوت: واضح وعنده خزينه جيده من الكلمات العربية.\nإضافات : الدكتور فضل يعشق الفيزيكس ويدرسه بطريقة تحببك فيها… مازلت اصر على رأيي ان فضل مكانه الجبل وليس الاوريا.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1492697-pyp001", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/fazal-ur-rehman/115380/11", "user": "To_Be_Engineer", "ts": 1526676102000, "tid": 115380, "pn": 11}}]}', 1526676102000, 1794835001, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-hms812-pyp001', 'stk-hms812', 'PYP 001', 'doc', '{"docs": [{"id": "stk-dr-f172587", "n": "Dr. Giacinto Genco", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "PYP001-161\n\nالتحضير: بداية الكلاس ، اذا جيت بعد وقت التحضير يحطك ليت وأحيانا يحطك حاضر ، الغياب عنده بعد 10 دقايق من بداية وقت المحاضرة\n\nطريقة الشرح: مملة جدا جدا ماراح تستفيد منه كثير ، هو صحيح متمكن من المنهج لكن يتكلم كثير في أشياء برا المنهج وماتستفيد منها في المياجر أبداً فإذا كنت تبي قريد لازم تتعب على نفسك\n\nالكويزات:متوسطة إلى صعبة موب أي أحد ياخذ فيها كامل والسبب انه يجيب في كل كويز سؤال أو سؤالين من برا المنهج هو يقول انها تدربكم للميجر بس مايجي منها شي وأفكارها معقدة\n\nالمياجر:كومون\n\nالفاينلات:كومون\n\nالصوت: واضح بلكنة إيطالية كان يصعب علي فهم بعض الكلمات فالبداية لكن مع الوقت صار الوضع اوكيه\n\nإضافات:الدكتور محترم وأخلاق، ويحب الطلاب كثير ودائما ينصحهم ويرحب بهم في الساعات المكتبية ، من بداية الى نهاية السمستر وهو يقول تعالوا المكتب ، اذا كنت تبي تجيب قريد لاتعتمد ع اللي يشرحه …\nاشتغل ع الكتاب + الاختبارات القديمة واذا ماعرفت تحل أي سؤال رح له المكتب (مجربنها)\n\nالقريد النهائي: C", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1467587-pyp001", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/giacinto-genco/172587/5", "user": "HMS812", "ts": 1486234832000, "tid": 172587, "pn": 5}}]}', 1486234832000, 1794835001, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-bader_alqahtani-pyp001', 'stk-bader_alqahtani', 'PYP 001', 'doc', '{"docs": [{"id": "stk-dr-f172587", "n": "Dr. Giacinto Genco", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "PYP001 161\nالتحضير:يحضر بداية الحصة\n\nالشرح:يشرح ملخبط م تدري وش قاعد يسوي دقيقة تلقاه يشرح و دقيقة يقعد ينكت و دقيقة يقلك قصة حياته 😂\n\nالاكسنت:يتكلم انقليزي بس اللغة الام تخرب عليه يعني ساعات م تدري يتكلم انقليزي ولا ايطالي\n\nالكوزات:صعبه و بعضها م مهي موجودة اصلا بالمنهج و تكون مرة صعبه يقلك عشان تجهزكم للميجر\n\nالمياجر :كومون\n\nالفاينال:كومون\n\nملاحظة:اذا انت تبغا تجيب درجة يبغالك تشد مرة لان غالب من يمسك المادة ذي لك عليهم", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1496320-pyp001", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/giacinto-genco/172587/9", "user": "Bader_Alqahtani", "ts": 1532452813000, "tid": 172587, "pn": 9}}]}', 1532452813000, 1794835001, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mjs-pyp001', 'stk-mjs', 'PYP 001', 'doc', '{"docs": [{"id": "stk-dr-f172587", "n": "Dr. Giacinto Genco", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "181-PYP001\nالتحضير : يحضر بداية الحصة ويمشي إذا تأخرت كم دقيقة\nطريقة الشرح : يستخدم سلايدات سيئة وغير ملمة للدرس\nالكويزات : متوسطة إلى صعبة ( معظم الأسئلة ما يغيرها فيتناقلونها الطلاب )\nالمياجر : كومن\nالفاينلات : كومن\nالصوت : واضح\nالقريد النهائي : جبت B+\n\nتقدر تعتمد على نفسك إذا كنت تبقى قريد", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1504671-pyp001", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/giacinto-genco/172587/11", "user": "MJS", "ts": 1546927481000, "tid": 172587, "pn": 11}}]}', 1546927481000, 1794835001, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user11372-pyp001', 'stk-user11372', 'PYP 001', 'doc', '{"docs": [{"id": "stk-dr-f176974", "n": "Dr. Hafiz Adil Qayyum", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "PYP001 - 182\n\nالتحضير : يحضر اول الكلاس من الموقع نفسه (درجاتي) حق الجامعة , ممكن تتاخر عنده ل 10 دقايق ويحطك Present لكن لاتفلها كل يوم لان الكلاس اللي بعده بيقولك انت كنت متأخر , ممنوع عنده الميك اب ابدا ولا يوم تسوي الا بعذر مثلا تسافر او كذا\n\nطريقة الشرح : يشرح من سلايدات عنده مثل حقت ابو الليث تقريبا , شرحه اقدر اقول جيد يعني مو سيئ ولا ممتاز وسط , المشكلة الوحيدة بكلاسه نوووووووووم , يجيب لك النوم مره وهو يتكلم ومايتحرك بالكلاس ! يعامل الطلاب رسميات مره مافي أي ردة فعل , هو شرحه جيد لكن النوم يخليك ماتفهم ولا كلمة ! نص الكلاس وهو يتكلم ماسك جواله او نايم على الطاولة\n\nالكويزات : تجي نسخ لصق من الاولد اقزام غالبا , اختبرنا 7 كويزات ومافي بونص كل كويز بتنزل لك درجته نفسه يعني مو مثل بعض الدكاترة , مره حط كويز نارررررررررر والافرج كان 2 من 10 بس كان من قوقل الاسئلة بس رفع اغلب الطلاب درجات في ذاك الكويز بس لانه كان صعب اما الباقي اولد اقزام , غالبا 5 اسئلة كل سؤال عليه درجتين\n\nالمياجر: كومن\n\nالفاينلات : كومن\n\nالقريد النهائي: B\n\nالصوت: لهجة انجليزية باكستانية , هو باكستاني , اول اسبوعين ممكن ماتفهم شي بعدين الوضع حبة حبة بيصير عادي\n\nإضافات : الدكتور نظامه رسميات شوي , لكن متساعد بالاوفيس لو رحت له تبي يحلك سؤال او كذا , اذا رجع يدرس بالجبل ما انصحك تنزل معه لان هذا بالاوريا وشوي كان الوضع لك عليه", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1508755-pyp001", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/hafiz-adil-qayyum/176974/3", "user": "user11372", "ts": 1555604964000, "tid": 176974, "pn": 3}}]}', 1555604964000, 1794835001, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
